interface GoogleRecaptchaResponse {
  success: boolean;
  score?: number;
  action?: string;
  "error-codes"?: string[];
}

/**
 * Validates a client-side token string against Google's verification servers.
 * @param {string} token The verification token generated by your Vue frontend.
 * @return {Promise<boolean>} True if the token is valid and scores as human.
 */
export async function validateRecaptcha(token: string): Promise<boolean> {
  const secretKey = process.env.RECAPTCHA_SECRET_KEY;

  if (!secretKey) {
    console.error(
      "Backend Configuration Error: RECAPTCHA_SECRET_KEY is not defined."
    );
    return false;
  }

  try {
    const response = await fetch("https://www.google.com/recaptcha/api/siteverify", {
      method: "POST",
      headers: {"Content-Type": "application/x-www-form-urlencoded"},
      body: new URLSearchParams({
        secret: secretKey,
        response: token,
      }),
    });

    if (!response.ok) {
      console.error(
        `Google API returned an invalid status code: ${response.status}`
      );
      return false;
    }

    const data = (await response.json()) as GoogleRecaptchaResponse;

    // reCAPTCHA v3 returns a score between 0.0 (bot) and 1.0 (human).
    // We enforce a baseline threshold floor of 0.5 for our contact form.
    if (data.success && data.score !== undefined && data.score >= 0.5) {
      return true;
    }

    console.warn(
      `reCAPTCHA verification rejected. Success status: ${data.success}, ` +
        `Score: ${data.score}`
    );
    return false;
  } catch (error) {
    console.error(
      "Network communication failure during reCAPTCHA verification:",
      error
    );
    return false;
  }
}
